// 0. 常量与策略持久化（M2/M3/M4）
// ============================================================

var PL_CUTOFF = '2026-10-01';
var PL_POLICY_KEY = 'PERIOD_LOCK_STATE';
var PL_POLICY_INIT_KEY = 'PERIOD_LOCK_POLICY_INIT';   // [审④] 初始化哨兵：置 '1' 后策略键丢失=收紧
var PL_LOCK_TIMEOUT_MS = 5000;
