// ============================================================
// RemoteTrigger.gs  v1.0  —  SMCN 标准化「手机远程触发」helper
// ------------------------------------------------------------
// 让任意 GAS 项目获得手机/云端 Web App 触发能力（复制到项目根即可）。
//
// 接入步骤：
//   1) 复制本文件到项目根目录
//   2) 新建 RemoteActions.gs，定义：
//        var REMOTE_ACTIONS = {
//          myaction: function(){ /* ... */ return "完成提示"; }
//        };
//        function doGet(e){
//          var r = _rtMaybeHandle(e); if (r) return r;   // ← 接管远程触发
//          /* 你原本的 doGet 逻辑（没有就返回状态 JSON） */
//        }
//      （若项目已有 doGet，把第一行改成调用 _rtMaybeHandle 即可，原逻辑放后面）
//   3) 在 onOpen 菜单加：.addItem('生成手机远程链接','showRemoteTriggerLinks')
//   4) 部署为 Web App（执行身份=我；访问=仅自己 或 任何人/匿名）
//
// 安全：首跑自动生成 REMOTE_TOKEN 存 Script Properties；调用须带 ?token=
// 触发：<WEBAPP_URL>?action=<动作>&token=<token>
//       内置动作：status（看状态）、_seturl（注册真实 URL，供菜单显示）
// ============================================================
var RT_VERSION = "RT1.0";

// 👇 REMOTE_WEBAPP_URL 由各系统的 RemoteActions.gs 定义（部署后的真实 Web App URL）。
//    运行时优先读取 Script Properties REMOTE_WEBAPP_URL（由 ?action=_seturl 写入，可热更新），
//    其次取本常量，最后才用 scriptId 推导（仅供示意，scriptId ≠ 部署ID，需校正）。
//    故此处不再声明该变量，避免与 RemoteActions.gs 的赋值冲突。

/**
 * 核心分发。返回 ContentService 响应；若无 action 参数则返回 null（调用方继续原有逻辑）。
 */
function _rtMaybeHandle(e) {
  e = e || {};
  var action = String(e.parameter.action || "").toLowerCase();
  if (!action) return null;

  var props = PropertiesService.getScriptProperties();
  var expected = props.getProperty("REMOTE_TOKEN");
  var isFirstRun = false;
  if (!expected) {
    expected = "SMCN-" + Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd") + "-" + _rtMakeShortToken(6);
    props.setProperty("REMOTE_TOKEN", expected);
    isFirstRun = true;
  }

  var ts = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyy-MM-dd HH:mm:ss");
  var token = String(e.parameter.token || "");

  if (token !== expected) {
    var errObj = {
      ok: false,
      error: "Invalid or missing token",
      hint: isFirstRun ? "Token initialized on first run. Open sheet menu '📱 生成手机远程链接' to view it." : undefined,
      ts: ts
    };
    // 首跑时一次性把刚生成的 token 回显，便于手机/云端首次配置（之后不再泄露）
    // FIX 2026-10-13: 首跑不再把 token 明文回显。
    //   原逻辑 if (isFirstRun) errObj.token = expected 在 ANYONE_ANONYMOUS 部署下，等于把长期 token
    //   送给任何拿到 URL 的匿名请求者 —— 随后即可获得 readRange / appendRows / patchCells / purgeRows
    //   的完整读写权。现在 token 一律通过菜单「📱 生成手机远程链接」给已登录的本人查看。
    return _rtResponse(errObj);
  }

  var result = { ok: true, action: action, version: RT_VERSION, ts: ts };
  try {
    if (action === "status") {
      result.message = "ok";
      result.actions = _rtActionList();
    } else if (action === "_seturl") {
      var u = String(e.parameter.url || "").trim();
      if (u) { props.setProperty("REMOTE_WEBAPP_URL", u); result.message = "REMOTE_WEBAPP_URL saved"; }
      else { result.ok = false; result.error = "missing url param"; }
    } else if (typeof REMOTE_ACTIONS === "object") {
      // 大小写不敏感查找：分发器早期把 action .toLowerCase()，但 REMOTE_ACTIONS 键是混合大小写
      // (checkLeaves/syncLeaves/cleanupLeaves/setupAmy/testAmySelf)，直接查会全部 miss。线性找一次即可。
      var _rtKey = null;
      for (var _k in REMOTE_ACTIONS) {
        if (String(_k).toLowerCase() === action && typeof REMOTE_ACTIONS[_k] === "function") { _rtKey = _k; break; }
      }
      if (_rtKey) {
        var out = REMOTE_ACTIONS[_rtKey](e);
        if (out !== undefined && out !== null) result.message = String(out);
      } else {
        result.message = "unknown action: " + action + ". available: " + _rtActionList().join(", ");
      }
    } else {
      result.message = "unknown action: " + action + ". available: " + _rtActionList().join(", ");
    }
  } catch (err) {
    result.ok = false;
    result.error = err.message;
  }
  return _rtResponse(result);
}

/** 列出所有可用动作（含内置）。 */
function _rtActionList() {
  var list = ["status", "_seturl"];
  if (typeof REMOTE_ACTIONS === "object") {
    for (var k in REMOTE_ACTIONS) {
      if (typeof REMOTE_ACTIONS[k] === "function" && list.indexOf(k) < 0) list.push(k);
    }
  }
  return list;
}

/**
 * V4.3.62 POST 分发 —— 与 _rtMaybeHandle 共用同一套 token 校验与动作分发，
 * 额外把解析后的 JSON body 挂在 e.postBody 上供动作函数读取（appendRows / patchCells 用）。
 * 返回 ContentService 响应；body 无 action 时返回 null（调用方继续原有逻辑）。
 */
function _rtMaybeHandlePost(e) {
  e = e || {};
  var body = {};
  try {
    if (e.postData && e.postData.contents) body = JSON.parse(e.postData.contents);
    else if (e.parameter && e.parameter.payload) body = JSON.parse(e.parameter.payload);
  } catch (err) {
    return _rtResponse({ ok: false, error: 'invalid JSON body: ' + ((err && err.message) || err) });
  }
  var action = String(body.action || (e.parameter && e.parameter.action) || '').toLowerCase();
  if (!action) return null;

  var params = {};
  var src = e.parameter || {};
  for (var k in src) params[k] = src[k];
  for (var k2 in body) { if (typeof body[k2] !== 'object') params[k2] = body[k2]; }
  params.action = action;
  if (!params.token && body.token) params.token = body.token;

  return _rtMaybeHandle({ parameter: params, postBody: body });
}

/** 统一 JSON 响应。 */
function _rtResponse(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

/** 生成短随机 token 后缀。 */
function _rtMakeShortToken(len) {
  var chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  var out = "";
  for (var i = 0; i < len; i++) out += chars.charAt(Math.floor(Math.random() * chars.length));
  return out;
}

/**
 * 菜单入口：显示当前 Web App URL + 各 action 的完整远程触发链接。
 * URL 优先取 Script Properties REMOTE_WEBAPP_URL（部署后由 _seturl 写入），
 * 其次取本文件常量 REMOTE_WEBAPP_URL，最后用 scriptId 推导（示意，需校正）。
 */
function showRemoteTriggerLinks() {
  var ui = SpreadsheetApp.getUi();
  if (!ui) return;
  var props = PropertiesService.getScriptProperties();
  var token = props.getProperty("REMOTE_TOKEN");
  if (!token) {
    token = "SMCN-" + Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd") + "-" + _rtMakeShortToken(6);
    props.setProperty("REMOTE_TOKEN", token);
  }
  var url = props.getProperty("REMOTE_WEBAPP_URL") || REMOTE_WEBAPP_URL ||
            ("https://script.google.com/a/macros/spacematrix.com/s/" + ScriptApp.getScriptId() + "/exec");
  var actions = _rtActionList().filter(function(a) { return a !== "_seturl"; });
  var links = "";
  actions.forEach(function(a) {
    var u = url + "?action=" + a + "&token=" + token;
    links += '<p><b>' + a + ':</b><br><a href="' + u + '" target="_blank">' + u + '</a></p>';
  });
  var html = '<h3>📱 SMCN 远程触发链接</h3>' +
    '<p><b>Web App URL:</b><br><code>' + url + '</code></p>' +
    '<p><b>Token:</b> <code>' + token + '</code></p><hr>' + links +
    '<p style="color:#666;font-size:12px;">把常用链接收藏到手机浏览器书签，或发给 WorkBuddy 手机端。' +
    'Token 存在 Script Properties，换设备也通用。如菜单链接打不开，说明 Web App URL 未校正，' +
    '点一次「部署」后在手机或电脑执行一次 <code>?action=_seturl&url=&lt;真实URL&gt;</code> 即可。</p>';
  ui.showModalDialog(HtmlService.createHtmlOutput(html).setWidth(700).setHeight(480), '📱 远程触发链接');
}

/**
 * 🔄 抓取设计脚本.gs (V3.5.4 智能兼容版)
 * 修复说明：升级获取目标表为智能模糊匹配，彻底解决因标签页名称含有隐藏空格而报错找不到的问题。
 */
function fetchArchiveData() {
  var sourceSpreadsheetId = '1UT1ySw3ByHd1BGUAq1FquJNg4dliwhd8VhhEak_W0IQ';
  var sourceSheetName = 'Archive_归档'; 
  
  var sourceSpreadsheet = SpreadsheetApp.openById(sourceSpreadsheetId);
  var sourceSheet = sourceSpreadsheet.getSheetByName(sourceSheetName);
  if (!sourceSheet) { SpreadsheetApp.getUi().alert('错误：找不到源文件中的“Archive_归档”工作表。'); return; }

  var sourceData = sourceSheet.getDataRange().getValues();
  var destSpreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  var destSheetName = '抓取设计的工时流水';
  
  // 【智能兼容修复】：遍历所有标签页，自动去除首尾空格并支持关键词模糊匹配，防止因肉眼看不见的空格报错
  var sheets = destSpreadsheet.getSheets();
  var destSheet = null;
  for (var s = 0; s < sheets.length; s++) {
    var currentTabName = sheets[s].getName().trim();
    if (currentTabName === destSheetName.trim() || currentTabName.indexOf('抓取设计') > -1) {
      destSheet = sheets[s];
      break;
    }
  }
  
  // 如果还是找不到，给出更具引导性的提示
  if (!destSheet) { 
    SpreadsheetApp.getUi().alert('错误：当前文件中找不到包含“抓取设计”的目标工作表，请检查该标签页是否被不小心删除了。'); 
    return; 
  }

  var destData = [];
  for (var i = 1; i < sourceData.length; i++) {
    var row = sourceData[i];
    if (!row[0] && !row[13]) continue;
    destData.push([
      row[13], row[13], getExactName(row[2]), "", "", row[0], row[12], row[4], "", row[1]
    ]);
  }

  if (destData.length > 0) {
    var lastRow = destSheet.getLastRow();
    if (lastRow > 1) {
      var lastColumn = destSheet.getLastColumn();
      // 清空旧数据时动态兼容列宽，防止清除范围越界
      destSheet.getRange(2, 1, lastRow, lastColumn > 10 ? lastColumn : 10).clearContent();
    }
    
    // 批量写入新抓取的数据
    destSheet.getRange(2, 1, destData.length, 10).setValues(destData);
    SpreadsheetApp.getActiveSpreadsheet().toast('已成功抓取 ' + destData.length + ' 条数据');
  } else {
    SpreadsheetApp.getUi().alert('源表中未发现有效数据。');
  }
}

/**
 * V4.3.25 #658: 每周五 09:00 由 Luby 邮箱给「本周还没填齐工时」的人发警告提醒
 * - 仅统计本周（周一 ~ 今天）工作日，某天工时 < 8 即视为未完成
 * - 发件人显示为 Luby（replyTo 回 Luby 真邮箱），提醒将影响当月考勤记录
 * - 触发器 setupTimesheetFridayReminder() 每周五 09:00 触发；也可菜单「📧 发送提醒」立即发
 */
// V4.3.77 [2026-10-15] Rita 指示：停用周五工时提醒邮件（先不发）。
// 开关置于函数最前端 ⇒ 定时触发与菜单「📧 发送提醒」手动调用均受控；
// 停用时只写内部台账 + 本地提示，不读任何表、不发任何邮件、不删任何触发器。
// 恢复：把 false 改 true、推一次 HEAD 即可，触发器无需重建。
const TIMESHEET_REMINDER_ENABLED = false;

function sendTeamTimesheetReminders() {
  if (!TIMESHEET_REMINDER_ENABLED) {
    try { _tsWriteLog('friday_reminder_disabled', 'Rita 2026-10-15 指示停用；触发器保留，改 true 后自动恢复'); } catch (e) {}
    try { SpreadsheetApp.getUi().toast('⚪ 周五工时提醒已停用（Rita 2026-10-15 指示）', '工时提醒', 5); } catch (e) {}
    return;
  }
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. 获取人员名单（邮箱）
  const userSheet = ss.getSheetByName("人员名单");
  if (!userSheet) {
    console.error("找不到名为 '人员名单' 的分页，请检查页面名称！");
    return;
  }
  const userData = userSheet.getDataRange().getValues();
  const emailMap = {};
  for (let i = 1; i < userData.length; i++) {
    const nameKey = userData[i][0].toString().trim();
    const emailVal = userData[i][1].toString().trim();
    if (nameKey) emailMap[nameKey] = emailVal;
  }

  // 2. 获取工时数据主表
  const dataSheet = ss.getSheets()[0];
  const data = dataSheet.getDataRange().getValues();
  const tz = "GMT+8";
  const todayStr = Utilities.formatDate(new Date(), tz, "yyyy/MM/dd");
  const spreadsheetUrl = ss.getUrl();

  // 3. 本周一 00:00 作为统计起点
  const now = new Date();
  const dow = now.getDay(); // 0=周日
  const mondayOffset = (dow === 0) ? -6 : (1 - dow);
  const monday = new Date(now);
  monday.setDate(now.getDate() + mondayOffset);
  monday.setHours(0, 0, 0, 0);
  const mondayStr = Utilities.formatDate(monday, tz, "yyyy/MM/dd");

  const BLACK = (typeof BLACKLIST !== 'undefined') ? BLACKLIST : [];

  // 4. 统计每人本周未完成的工作日
  const incompleteMap = {};
  for (let i = 1; i < data.length; i++) {
    const row = data[i];
    const nameInSheet = row[0].toString().trim();
    const dateValue = row[2];
    const hoursFilled = parseFloat(row[3]) || 0;

    if (!nameInSheet) continue;
    if (BLACK.indexOf(nameInSheet) > -1) continue;

    // 解析日期（兼容 Date 与可转 Date 的值）
    let d = null;
    if (dateValue instanceof Date) d = dateValue;
    else if (dateValue) { const t = new Date(dateValue); if (!isNaN(t.getTime())) d = t; }
    if (!d) continue;

    const dStr = Utilities.formatDate(d, tz, "yyyy/MM/dd");
    if (dStr < mondayStr || dStr > todayStr) continue; // 仅本周一 ~ 今天
    const dw = d.getDay();
    if (dw === 0 || dw === 6) continue; // 周末不计入

    if (hoursFilled < 8) {
      if (!incompleteMap[nameInSheet]) incompleteMap[nameInSheet] = [];
      const md = Utilities.formatDate(d, tz, "MM/dd");
      incompleteMap[nameInSheet].push(md + " (" + hoursFilled + "h)");
    }
  }

  // 5. 逐个发送（从 Luby 邮箱发出）
  let sent = 0;
  for (const name in incompleteMap) {
    const targetEmail = emailMap[name];
    if (!targetEmail) { console.warn("未能在'人员名单'中找到 " + name + " 的邮箱"); continue; }
    sendFridayReminder(targetEmail, name, incompleteMap[name], spreadsheetUrl);
    sent++;
  }
  console.log("周五提醒已发送 " + sent + " 封（本周未完成人数）");
  try { SpreadsheetApp.getUi().toast("📧 周五提醒已发送 " + sent + " 封", "工时提醒", 5); } catch (e) {}
}

function sendFridayReminder(email, name, days, url) {
  const subject = "[工时填报警告 / Timesheet Alert] " + name + "，你本周还有 " + days.length + " 天工时未填齐，将影响当月考勤记录";
  const dayList = days.map(function(d) { return "  • " + d; }).join("\n");
  const body =
    "你好 " + name + "，\n\n" +
    "系统检测到你本周（周一至今）以下工作日的工时记录尚未填齐（不足 8 小时）：\n" +
    dayList + "\n\n" +
    "⚠️ 重要提醒：工时记录是考勤依据。请务必在本月内（建议次月 5 日前）补齐上述日期的工时，\n" +
    "逾期未完成将计入考勤异常，影响当月出勤与薪资核算。\n\n" +
    "请尽快登录填写：" + url + "\n\n" +
    "— Luby Huang (Space Matrix 运营)";
  MailApp.sendEmail({
    to: email,
    subject: subject,
    body: body,
    name: "Luby",
    replyTo: "luby@spacematrix.com"
  });
  console.log("周五提醒已发送至：" + name + " (" + email + ")");
}

/**
 * V4.3.25 #658: 设置「每周五 09:00」自动提醒触发器（幂等，重复运行只保留一个）
 */
function setupTimesheetFridayReminder() {
  const triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === 'sendTeamTimesheetReminders') {
      ScriptApp.deleteTrigger(triggers[i]);
    }
  }
  ScriptApp.newTrigger('sendTeamTimesheetReminders')
    .timeBased().onWeekDay(ScriptApp.WeekDay.FRIDAY).atHour(9).create();
  SpreadsheetApp.getUi().alert(
    "⏰ 每周五 09:00 自动提醒已开启！\n\n" +
    "每周五上午 9 点，系统会以 Luby 的邮箱给本周工时未填齐的同事发送警告提醒，\n" +
    "提醒其尽快补齐，逾期将影响当月考勤记录。\n\n" +
    "（也可在「📧 发送提醒」菜单立即手动发送一次）"
  );
}
